-- KRS College Connect Football - consolidated schema (generated by scripts/football/build-schema.py)
-- Paste into a brand-new Supabase project SQL editor. Inherited soccer migrations first, football changes last.

-- ============ migrations/001_create_organizations.sql ============
-- Create organizations table (tenant table)
create table if not exists organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  short_name text,
  slug text unique not null,
  logo_url text,
  primary_color text default '#dc2626',
  secondary_color text default '#0a1628',
  locale text,
  active boolean default true,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Enable RLS
alter table organizations enable row level security;

-- Seed Eastside FC as the pilot organization
insert into organizations (
  id,
  name,
  short_name,
  slug,
  logo_url,
  primary_color,
  secondary_color,
  locale
) values (
  'b0000000-0000-0000-0000-000000000001',
  'Mercer Island High School Football',
  'Mercer Island',
  'mercer-island-hs-football',
  null, -- will be added later
  '#8C1D40', -- maroon
  '#FFFFFF', -- white
  'Mercer Island, WA'
) on conflict (id) do nothing;
-- ============ migrations/002_create_org_members.sql ============
-- Create org_members table (links auth users to organizations)
create table if not exists org_members (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references organizations(id) on delete cascade not null,
  user_id uuid references auth.users(id) on delete cascade not null,
  role text not null check (role in ('admin', 'athlete')),
  created_at timestamptz default now(),
  unique (org_id, user_id)
);

-- Enable RLS
alter table org_members enable row level security;

-- RLS policy: users read only their own membership rows
create policy "Users read own memberships"
  on org_members for select
  using (user_id = auth.uid());

-- Index for performance
create index if not exists idx_org_members_user on org_members (user_id);
create index if not exists idx_org_members_org on org_members (org_id);
-- ============ migrations/003_create_profiles.sql ============
-- Create profiles table (extended user info)
create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  org_id uuid references organizations(id),
  email text,
  full_name text,
  role text,
  onboarding_complete boolean default false,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Enable RLS
alter table profiles enable row level security;

-- RLS policy: users read own profile
create policy "Users read own profile"
  on profiles for select
  using (id = auth.uid());

-- RLS policy: users update own profile
create policy "Users update own profile"
  on profiles for update
  using (id = auth.uid());

-- Index for performance
create index if not exists idx_profiles_org on profiles (org_id);
-- ============ migrations/004_create_athletes.sql ============
-- Create athletes table (athlete-specific data)
create table if not exists athletes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade unique not null,
  org_id uuid references organizations(id) not null,
  position text,
  class_year int,
  gpa numeric(3,2),
  height_cm int,
  bio text,
  highlight_reel_url text,
  onboarding_complete boolean default false,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Enable RLS
alter table athletes enable row level security;

-- RLS policy: athletes read own data
create policy "Athletes read own data"
  on athletes for select
  using (user_id = auth.uid());

-- RLS policy: athletes update own data
create policy "Athletes update own data"
  on athletes for update
  using (user_id = auth.uid());

-- RLS policy: athletes insert own data
create policy "Athletes insert own data"
  on athletes for insert
  with check (user_id = auth.uid());

-- Index for performance
create index if not exists idx_athletes_user on athletes (user_id);
create index if not exists idx_athletes_org on athletes (org_id);
-- ============ migrations/005_create_invite_codes.sql ============
-- Create invite_codes table
create table if not exists invite_codes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references organizations(id) not null,
  code text unique not null,
  label text,
  max_uses int,
  uses int default 0,
  active boolean default true,
  expires_at timestamptz,
  created_at timestamptz default now()
);

-- Enable RLS
alter table invite_codes enable row level security;

-- Index for performance
create index if not exists idx_invite_codes_org on invite_codes (org_id);
create index if not exists idx_invite_codes_code on invite_codes (code);


-- ============ migrations/006_create_pipelines.sql ============
-- Create pipelines table (the "My Schools" table)
create table if not exists pipelines (
