-- ============ migrations/018_coaches_unique_constraint.sql ============
-- Add unique constraint on coaches table for upsert operations
-- Migration 018: Coaches Unique Constraint

-- Add unique constraint on (school_id, name) if it doesn't already exist
-- This is needed for the scraper's onConflict: 'school_id,name' parameter

DO $$
BEGIN
    -- Check if constraint already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'coaches_school_name_unique'
    ) THEN
        -- Add the unique constraint
        ALTER TABLE coaches
        ADD CONSTRAINT coaches_school_name_unique
        UNIQUE (school_id, name);

        RAISE NOTICE 'Added unique constraint on coaches(school_id, name)';
    ELSE
        RAISE NOTICE 'Unique constraint on coaches(school_id, name) already exists';
    END IF;
END $$;
-- ============ migrations/019_outreach_schema.sql ============
-- Outreach Tool Database Schema
-- Migration 019: Outreach Schema

-- Create outreach_log table for tracking all outreach activities
CREATE TABLE IF NOT EXISTS outreach_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  athlete_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
  org_id uuid REFERENCES organizations(id),
  coach_id uuid REFERENCES coaches(id) ON DELETE SET NULL,
  school_id uuid REFERENCES schools(id) ON DELETE CASCADE,
  template_type text CHECK (template_type IN ('initial', 'follow_up', 'highlight_share', 'campus_visit', 'thank_you_camp', 'schedule_update', 'custom')),
  subject text,
  body text,
  sent_method text CHECK (sent_method IN ('copied_to_clipboard', 'opened_mail_app', 'marked_sent_manually')),
  sent_at timestamptz DEFAULT now(),
  coach_replied boolean DEFAULT false,
