  ON outreach_templates FOR ALL
  TO authenticated
  USING (
    org_id IN (
      SELECT om.org_id
      FROM org_members om
      WHERE om.user_id = auth.uid()
      AND om.role = 'admin'
    )
  )
  WITH CHECK (
    org_id IN (
