-- ============ migrations/032_org_nil_deals.sql ============
-- Admin-managed sponsor deals (org-level NIL partnerships)
-- Directors/admins create these; athletes see them in the NIL Deals section.
-- This is separate from the athlete-scoped nil_deals table (008) which tracks
-- individual athlete deal applications/history.

create table if not exists org_nil_deals (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid references organizations(id) not null,
  created_by      uuid references auth.users(id),

  -- Sponsor identity
  brand           text not null,
  logo_abbrev     text,          -- e.g. "NIKE", shown in brand avatar
  logo_color      text,          -- hex, e.g. "#000000"

  -- Classification
  category        text,          -- e.g. "Apparel", "Food & Bev", "Tech", "Local biz"
  deal_type       text,          -- e.g. "gear", "camps", "coaching", "apparel", "cash", "product"

  -- Compensation
  value           numeric,       -- numeric amount for sorting/filtering
  payout_display  text,          -- human-readable string, e.g. "$500 – $1,500"

  -- Details
  description     text,
  requirements    text,
  expiration_date date,

  -- Targeting
  applies_to      text default 'all',  -- 'all' | 'grad_year' | 'specific'
  grad_years      int[],               -- e.g. {2025, 2026} when applies_to = 'grad_year'

  -- Lifecycle
  status          text default 'Open', -- 'Open' | 'Closed'
  featured        boolean default false,
  created_at      timestamptz default now(),
  updated_at      timestamptz default now()
);

-- Enable RLS
alter table org_nil_deals enable row level security;

-- All org members (athletes + admins) can read their org's deals
create policy "Org members read org nil deals"
  on org_nil_deals for select
  using (
    org_id in (
      select org_id from org_members where user_id = auth.uid()
    )
  );

-- Only admins in the org can create deals
create policy "Admins insert org nil deals"
  on org_nil_deals for insert
  with check (
    org_id in (
      select org_id from org_members
      where user_id = auth.uid() and role = 'admin'
    )
  );

-- Only admins in the org can update deals
create policy "Admins update org nil deals"
  on org_nil_deals for update
  using (
    org_id in (
      select org_id from org_members
      where user_id = auth.uid() and role = 'admin'
    )
  );

-- Only admins in the org can delete deals
create policy "Admins delete org nil deals"
  on org_nil_deals for delete
  using (
    org_id in (
      select org_id from org_members
      where user_id = auth.uid() and role = 'admin'
    )
  );

-- Indexes
create index if not exists idx_org_nil_deals_org on org_nil_deals (org_id);
create index if not exists idx_org_nil_deals_status on org_nil_deals (status);

-- ============ migrations/034_highlight_videos.sql ============
-- ============================================================
-- 034_highlight_videos.sql
-- Mux-powered highlight video clips for athletes.
-- Each row = one uploaded clip; reel_order determines public
-- display sequence on the athlete's profile.
-- ============================================================

CREATE TABLE IF NOT EXISTS highlight_videos (
  id                UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  athlete_id        UUID        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,

  -- Mux upload / asset tracking
  mux_upload_id     TEXT,                          -- Mux direct-upload ID (while uploading)
  mux_asset_id      TEXT,                          -- Mux asset ID (once processing starts)
  mux_playback_id   TEXT,                          -- Mux playback ID (once ready)

  -- Clip metadata
  title             TEXT        NOT NULL DEFAULT 'Untitled Clip',
  status            TEXT        NOT NULL DEFAULT 'uploading',
  -- status values: uploading | processing | ready | errored

  duration          FLOAT,                         -- total duration in seconds (from Mux)

  -- Trim points (stored as metadata; applied at playback time via player startTime)
  start_time        FLOAT       NOT NULL DEFAULT 0,
  end_time          FLOAT,                         -- NULL = play to end

  -- Overlay metadata (CSS overlay shown on player — NOT burned into video)
  overlay_name      TEXT,
  overlay_position  TEXT,
  overlay_jersey    TEXT,

  -- Reel ordering (lower = plays first on public profile)
  reel_order        INTEGER     NOT NULL DEFAULT 0,

  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Row-level security
ALTER TABLE highlight_videos ENABLE ROW LEVEL SECURITY;

-- Athletes can do everything with their own clips
CREATE POLICY "Athletes manage own highlight_videos"
  ON highlight_videos
  FOR ALL
  USING (auth.uid() = athlete_id);

-- Anyone (coaches, unauthenticated) can read ready clips
CREATE POLICY "Public can read ready highlight_videos"
  ON highlight_videos
  FOR SELECT
  USING (status = 'ready');

-- Auto-update updated_at
CREATE OR REPLACE FUNCTION _update_highlight_videos_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER highlight_videos_updated_at
  BEFORE UPDATE ON highlight_videos
  FOR EACH ROW EXECUTE FUNCTION _update_highlight_videos_updated_at();

-- Index for quick athlete lookups sorted by reel order
CREATE INDEX IF NOT EXISTS highlight_videos_athlete_order
  ON highlight_videos (athlete_id, reel_order);

-- ============ migrations/035_performance_indexes.sql ============
-- ============================================================
-- 035_performance_indexes.sql
-- Performance indexes for scale: 3,000 athletes × 150 clubs.
-- Safe to re-run — every statement uses IF NOT EXISTS.
--
-- Note: Many single-column indexes already exist from earlier
-- migrations (001–034). This file adds only the gaps:
-- missing single-column indexes and composite indexes for
-- the most common multi-column filter patterns.
-- ============================================================

-- ─────────────────────────────────────────────
-- athletes
-- (user_id, org_id already indexed in 004)
-- ─────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_athletes_position
  ON athletes (position);

CREATE INDEX IF NOT EXISTS idx_athletes_class_year
  ON athletes (class_year);

-- Composite: org roster filtered by grad year (admin view)
CREATE INDEX IF NOT EXISTS idx_athletes_org_class_year
  ON athletes (org_id, class_year);

-- Composite: org roster filtered by position (admin view)
CREATE INDEX IF NOT EXISTS idx_athletes_org_position
  ON athletes (org_id, position);

-- ─────────────────────────────────────────────
-- profiles
-- (org_id already indexed in 003)
-- profiles.id IS the auth user_id — no extra index needed.
-- ─────────────────────────────────────────────

-- ─────────────────────────────────────────────
-- pipelines
-- (athlete_id, org_id already indexed in 006)
-- ─────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_pipelines_status
  ON pipelines (status);

-- Composite: athlete's schools by stage (My Schools page)
CREATE INDEX IF NOT EXISTS idx_pipelines_athlete_status
  ON pipelines (athlete_id, status);

-- Composite: admin view — all pipelines for an org, by stage
CREATE INDEX IF NOT EXISTS idx_pipelines_org_status
  ON pipelines (org_id, status);

-- ─────────────────────────────────────────────
-- schools
-- (division, conference, region, state already indexed in 012)
-- ─────────────────────────────────────────────

-- Text search on school name (LIKE 'term%' queries use this)
CREATE INDEX IF NOT EXISTS idx_schools_name
  ON schools (name);

-- Composite: Coach Finder filters by division + conference
CREATE INDEX IF NOT EXISTS idx_schools_division_conference
  ON schools (division, conference);

-- ─────────────────────────────────────────────
-- coaches
-- (school_id, org_id, visibility already indexed in 012)
-- ─────────────────────────────────────────────

-- Composite: coaches for a school visible to a given org
CREATE INDEX IF NOT EXISTS idx_coaches_school_visibility
  ON coaches (school_id, visibility);

-- ─────────────────────────────────────────────
-- highlight_videos
-- (athlete_id, reel_order composite already indexed in 034)
-- ─────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_highlight_videos_status
  ON highlight_videos (status);

-- Composite: athlete's ready clips (public profile reel)
CREATE INDEX IF NOT EXISTS idx_highlight_videos_athlete_status
  ON highlight_videos (athlete_id, status);

-- ─────────────────────────────────────────────
-- org_nil_deals
-- (org_id, status already indexed in 032)
-- ─────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_org_nil_deals_expiration_date
  ON org_nil_deals (expiration_date);

-- Composite: org's open deals (athlete NIL Deals page)
CREATE INDEX IF NOT EXISTS idx_org_nil_deals_org_status
  ON org_nil_deals (org_id, status);

-- ─────────────────────────────────────────────
-- org_members
-- (user_id, org_id already indexed in 002)
-- ─────────────────────────────────────────────

-- Composite: find all admins (or athletes) in a given org
CREATE INDEX IF NOT EXISTS idx_org_members_org_role
  ON org_members (org_id, role);

-- ─────────────────────────────────────────────
-- Update query planner statistics
-- ─────────────────────────────────────────────
ANALYZE athletes;
ANALYZE profiles;
ANALYZE pipelines;
ANALYZE schools;
ANALYZE coaches;
ANALYZE highlight_videos;
ANALYZE org_nil_deals;
ANALYZE org_members;

-- ============ migrations/036_admin_remove_members.sql ============
-- 036_admin_remove_members.sql
-- Allow org admins to remove members from their own org (soft removal —
-- AdminAthletes UI deletes the org_members row + nulls profiles.org_id;
-- the user's auth + profile + recruiting data are preserved).
CREATE POLICY "Admins remove org members"
  ON org_members
  FOR DELETE
  TO authenticated
  USING (
    org_id IN (
      SELECT org_id FROM org_members
      WHERE user_id = auth.uid() AND role = 'admin'
    )
    AND user_id <> auth.uid()
  );

CREATE POLICY "Admins update org member profiles"
  ON profiles
  FOR UPDATE
  TO authenticated
  USING (
    org_id IN (
      SELECT org_id FROM org_members
      WHERE user_id = auth.uid() AND role = 'admin'
    )
    AND id <> auth.uid()
  )
  WITH CHECK (
    org_id IS NULL
    OR org_id IN (
      SELECT org_id FROM org_members
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

