-- ============ migrations/047_atomic_invite_consume.sql ============
-- 047_atomic_invite_consume.sql
-- Atomic invite-code consumption RPC. The old flow in
-- api/admin/validate-invite.js was a SELECT-then-UPDATE pair that two
-- concurrent signups could race: both reads see uses=2 with max_uses=3,
-- both writes set uses=3, and you've now leaked an extra signup past
-- the cap. Worse, the endpoint trusted a client-supplied userId.
--
-- The hardened endpoint now:
--   * Pulls user identity from the verified JWT (auth.getUser), never
--     from the request body.
--   * Calls consume_invite_code(p_code) which row-locks the invite
--     (SELECT … FOR UPDATE) and returns (org_id, ok, reason).
--   * Returns a generic "Invalid or expired" message for any failure
--     so attackers can't distinguish not_found / expired / exhausted.
--
-- SECURITY DEFINER + locked search_path lets this function bypass RLS
-- on invite_codes without exposing it to anon / authenticated. Only
-- the service_role JWT (used by the Vercel function) can call it.

CREATE OR REPLACE FUNCTION public.consume_invite_code(p_code text)
RETURNS TABLE (org_id uuid, ok boolean, reason text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invite invite_codes%ROWTYPE;
BEGIN
  SELECT * INTO v_invite
    FROM invite_codes
   WHERE code = p_code
     AND active = true
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::uuid, false, 'not_found';
    RETURN;
  END IF;

  IF v_invite.expires_at IS NOT NULL AND v_invite.expires_at < NOW() THEN
    RETURN QUERY SELECT NULL::uuid, false, 'expired';
    RETURN;
  END IF;

  IF v_invite.max_uses IS NOT NULL AND v_invite.uses >= v_invite.max_uses THEN
    RETURN QUERY SELECT NULL::uuid, false, 'exhausted';
    RETURN;
  END IF;

  UPDATE invite_codes
     SET uses = uses + 1
   WHERE id = v_invite.id;

  RETURN QUERY SELECT v_invite.org_id, true, NULL::text;
END;
$$;

REVOKE ALL ON FUNCTION public.consume_invite_code(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_invite_code(text) TO service_role;

-- ============ migrations/048_public_profile_rpcs.sql ============
-- 048_public_profile_rpcs.sql
--
-- Phase 2 corrigendum — replaces the public-profile privacy approach
-- introduced in 045_public_profile_privacy.sql.
--
-- WHY 045 WAS BROKEN
-- ------------------
-- 045 created `public_athlete_profiles` and `public_athlete_milestones`
-- SECURITY INVOKER views. Under SECURITY INVOKER the view executes with
-- the privileges of the caller, so for `anon` to read through the view
-- the underlying base tables had to allow anon SELECT. 045 did this by
-- adding `USING (true)` RLS policies on profiles, athletes, highlights,
-- and athlete_milestones.
--
-- That is a column-leak: RLS only filters rows, never columns. An anon
-- caller could ignore the view entirely and run
--   .from('athletes').select('*').eq('user_id', X)
-- to retrieve GPA, SAT, ACT, height_cm, weight, intended_major, plus
-- every other column the view was supposed to hide. Because these are
-- minor athletes, that's a privacy incident, not a policy bug.
--
-- WHAT THIS MIGRATION DOES
-- ------------------------
-- 1. Drops the `USING (true)` policies and the SECURITY INVOKER views
--    from 045.
-- 2. Belt-and-suspenders REVOKE: removes direct anon SELECT on the
--    sensitive base tables (profiles, athletes, pipelines, outreach,
--    highlights, highlight_videos, athlete_milestones, school_notes,
--    recruiting_activity, scheduled_camps, camp_expenses).
--    PostgREST grants these to anon by default; without an explicit
--    REVOKE, a future migration that accidentally adds a permissive
--    policy would reopen the hole. With the GRANT itself gone, anon
--    physically cannot read these tables — RLS is no longer the only
--    line of defense.
-- 3. Creates four SECURITY DEFINER RPC functions for the public
--    profile page. Each function explicitly enumerates the columns it
--    returns — there is no SELECT * and no path for the caller to ask
--    for more than the function's declared TABLE() type.
--      * get_public_athlete_profile(p_profile_id uuid)
--      * get_public_athlete_highlights(p_athlete_id uuid)
--      * get_public_athlete_primary_highlight(p_athlete_id uuid)
--      * get_public_athlete_milestones(p_athlete_id uuid)
-- 4. EXECUTE is granted only to anon + authenticated. All other roles
--    must use the base tables under their normal RLS.
--
-- WHY THIS CANNOT LEAK PRIVATE DATA
-- ---------------------------------
-- * anon has no direct SELECT grant on profiles / athletes / pipelines /
--   outreach / highlights / highlight_videos / athlete_milestones /
--   school_notes / recruiting_activity / scheduled_camps / camp_expenses.
--   Asking PostgREST for `from('athletes')` now returns 401, not data.
-- * The RPC functions run as the function owner with `SECURITY DEFINER`
--   so they can read the base tables, but each function body lists the
--   exact column projection. Height (height_cm), GPA, SAT, ACT, weight,
--   intended major, pipeline strategy, outreach, recruiting activity,
--   and private notes appear in zero function bodies. Adding them
--   would require an explicit code change in this file.
-- * search_path is locked to `public, pg_temp` so a malicious schema
--   shim cannot intercept the function's table references.
-- * Highlights are filtered to status='ready' AND reel_order > 0 inside
--   the function, so half-uploaded clips and clips the athlete has not
--   added to the reel are never returned.
-- * The functions are STABLE (no writes) and operate on a single
--   athlete_id argument, so the read is cacheable at the CDN edge.

-- ── 1. Reverse the broken policies and views from 045 ──────────────
DROP POLICY IF EXISTS "Public minimal profile fields"             ON profiles;
DROP POLICY IF EXISTS "Public minimal athlete fields"             ON athletes;
DROP POLICY IF EXISTS "Public read highlights"                    ON highlights;
DROP POLICY IF EXISTS "Public read athlete milestones for profile" ON athlete_milestones;

DROP VIEW IF EXISTS public.public_athlete_profiles;
DROP VIEW IF EXISTS public.public_athlete_milestones;

-- ── 2. Revoke direct anon SELECT on sensitive base tables ──────────
-- Idempotent: REVOKE on a grant that doesn't exist is a no-op.
-- authenticated keeps its SELECT grant; per-row RLS continues to
-- enforce ownership/org-membership for logged-in users.
REVOKE SELECT ON public.profiles            FROM anon;
REVOKE SELECT ON public.athletes            FROM anon;
REVOKE SELECT ON public.pipelines           FROM anon;
REVOKE SELECT ON public.outreach            FROM anon;
REVOKE SELECT ON public.highlights          FROM anon;
REVOKE SELECT ON public.highlight_videos    FROM anon;
REVOKE SELECT ON public.athlete_milestones  FROM anon;
REVOKE SELECT ON public.school_notes        FROM anon;
REVOKE SELECT ON public.recruiting_activity FROM anon;

-- Best-effort revokes on tables that exist conditionally (no-op if
-- the table is absent in a particular environment).
DO $$
BEGIN
  IF to_regclass('public.scheduled_camps') IS NOT NULL THEN
    EXECUTE 'REVOKE SELECT ON public.scheduled_camps FROM anon';
  END IF;
  IF to_regclass('public.camp_expenses') IS NOT NULL THEN
    EXECUTE 'REVOKE SELECT ON public.camp_expenses FROM anon';
  END IF;
END $$;

-- organizations stays anon-readable: it holds only org branding
-- (name, slug, colors, logo_url) and is needed by the signup page to
-- show "you're joining Eastside FC" before the user has a session.
-- No private data lives in this table.

-- ── 3. SECURITY DEFINER RPC: athlete profile + org branding ────────
-- Returns the single profile + joined org branding. Columns are an
-- explicit allow-list — every field here was reviewed against the
-- "minors privacy" exclusion list. Not present: height_cm, gpa, sat,
-- act, weight, intended_major, club_team_division, gpa_unweighted,
-- recruiting_status, any pipeline / outreach / notes fields.

-- Note: `position` is a SQL reserved word — Postgres rejects it as a
-- bare identifier in the RETURNS TABLE clause even though it's fine
-- as a column reference in SELECT. Double-quoting preserves the
-- column name as `position` for PostgREST consumers.
CREATE OR REPLACE FUNCTION public.get_public_athlete_profile(p_profile_id uuid)
RETURNS TABLE (
  id                     uuid,
  full_name              text,
  "position"             text,
  class_year             integer,
  jersey_number          integer,
  dominant_foot          text,
  club_team              text,
  high_school            text,
  city                   text,
  state                  text,
  bio                    text,
  profile_photo_url      text,
  instagram_url          text,
  twitter_url            text,
  tiktok_url             text,
  youtube_url            text,
  hudl_url               text,
  youtube_highlights_url text,
  veo_link_url           text,
  highlight_reel_url     text,
  org_id                 uuid,
  org_name               text,
  org_slug               text,
  org_primary_color      text,
  org_secondary_color    text,
  org_logo_url           text
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT
    p.id,
    p.full_name,
    a.position,
    a.class_year,
    a.jersey_number,
    a.dominant_foot,
    a.club_team,
    a.high_school,
    a.city,
    a.state,
    a.bio,
    a.profile_photo_url,
    a.instagram_url,
    a.twitter_url,
    a.tiktok_url,
    a.youtube_url,
    a.hudl_url,
    a.youtube_highlights_url,
    a.veo_link_url,
    a.highlight_reel_url,
    p.org_id,
    o.name,
    o.slug,
    o.primary_color,
    o.secondary_color,
    o.logo_url
  FROM public.profiles p
  LEFT JOIN public.athletes      a ON a.user_id = p.id
  LEFT JOIN public.organizations o ON o.id      = p.org_id
  WHERE p.id   = p_profile_id
    AND p.role = 'athlete';
$$;

REVOKE ALL ON FUNCTION public.get_public_athlete_profile(uuid) FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.get_public_athlete_profile(uuid) TO anon, authenticated;

-- ── 4. SECURITY DEFINER RPC: published highlight reel ──────────────
-- Returns only Mux clips with status='ready' AND reel_order > 0
-- (i.e. clips the athlete has explicitly added to their reel). Storage
-- paths, upload tokens, and any internal Mux asset metadata stay
-- internal — the projection here is exactly what the public player
-- needs and nothing more.

CREATE OR REPLACE FUNCTION public.get_public_athlete_highlights(p_athlete_id uuid)
RETURNS TABLE (
  id               uuid,
  mux_playback_id  text,
  title            text,
  start_time       numeric,
  end_time         numeric,
  duration         numeric,
  overlay_name     text,
  overlay_position text,
  overlay_jersey   text,
  reel_order       integer
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT
    hv.id,
    hv.mux_playback_id,
    hv.title,
    hv.start_time,
    hv.end_time,
    hv.duration,
    hv.overlay_name,
    hv.overlay_position,
    hv.overlay_jersey,
    hv.reel_order
  FROM public.highlight_videos hv
  WHERE hv.athlete_id = p_athlete_id
    AND hv.status     = 'ready'
    AND hv.reel_order IS NOT NULL
    AND hv.reel_order > 0
  ORDER BY hv.reel_order ASC
  LIMIT 10;
$$;

REVOKE ALL ON FUNCTION public.get_public_athlete_highlights(uuid) FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.get_public_athlete_highlights(uuid) TO anon, authenticated;

-- ── 5. SECURITY DEFINER RPC: legacy primary highlight fallback ─────
-- The legacy `highlights` table is the pre-Mux YouTube/Hudl link
-- fallback. Only `is_primary = true` rows are exposed. URLs, titles,
-- source, and thumbnail are the only columns the public player needs.

CREATE OR REPLACE FUNCTION public.get_public_athlete_primary_highlight(p_athlete_id uuid)
RETURNS TABLE (
  url           text,
  title         text,
  source        text,
  thumbnail_url text
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT h.url, h.title, h.source, h.thumbnail_url
  FROM public.highlights h
  WHERE h.athlete_id = p_athlete_id
    AND h.is_primary = true
  LIMIT 1;
$$;

REVOKE ALL ON FUNCTION public.get_public_athlete_primary_highlight(uuid) FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.get_public_athlete_primary_highlight(uuid) TO anon, authenticated;

-- ── 6. SECURITY DEFINER RPC: earned badges (milestones) ────────────
-- Returns only the milestone_id + earned_at pair. The athlete_milestones
-- table also holds org_id and internal metadata; those stay private.
-- The frontend resolves milestone_id -> name/icon from a static
-- milestones definition that's already public in the bundle.

CREATE OR REPLACE FUNCTION public.get_public_athlete_milestones(p_athlete_id uuid)
RETURNS TABLE (
  milestone_id text,
  earned_at    timestamptz
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT am.milestone_id, am.earned_at
  FROM public.athlete_milestones am
  WHERE am.user_id = p_athlete_id
  ORDER BY am.earned_at DESC
  LIMIT 50;
$$;

REVOKE ALL ON FUNCTION public.get_public_athlete_milestones(uuid) FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.get_public_athlete_milestones(uuid) TO anon, authenticated;

-- ============ migrations/049_complete_with_check.sql ============
-- 049_complete_with_check.sql
--
-- Two RLS policies that 044_security_hardening_with_check.sql missed:
--
--   (1) profiles "Users update own profile" — was FOR UPDATE with only
--       a USING clause. An authenticated user could UPDATE their own
--       profile row and (because no WITH CHECK) set role='admin' or
--       move themselves to a different org_id. That's a privilege
--       escalation path.
--
--   (2) highlight_videos "Athletes manage own highlight_videos" — FOR
--       ALL with only USING. The INSERT/UPDATE branches of ALL had no
--       WITH CHECK, so an authenticated user could INSERT a clip row
--       claiming athlete_id of a different user. Impersonation path.
--
-- This migration:
--   * Adds WITH CHECK to both policies via ALTER POLICY.
--   * Installs a BEFORE-UPDATE trigger on profiles that hard-blocks any
--     attempt by an authenticated user to mutate role, org_id, or id.
--     RLS WITH CHECK alone could be tightened to forbid role escalation
--     but only at the cost of a subquery on profiles inside a profiles
--     policy, which would recurse. A trigger is the standard escape
--     hatch.
--
-- service_role bypasses RLS and triggers via the trigger guard's role
-- check, so admin/server flows that legitimately change role/org_id
-- (validate-invite, admin promotion) still work.

-- ── 1. profiles UPDATE policy: add WITH CHECK ────────────────────
ALTER POLICY "Users update own profile" ON public.profiles
  USING (id = auth.uid())
  WITH CHECK (id = auth.uid());

-- ── 2. highlight_videos ALL policy: add WITH CHECK ───────────────
ALTER POLICY "Athletes manage own highlight_videos" ON public.highlight_videos
  USING (auth.uid() = athlete_id)
  WITH CHECK (auth.uid() = athlete_id);

-- ── 3. Trigger: block role/org_id/id mutation on profiles ────────
-- WITH CHECK alone says "the new row must satisfy id = auth.uid()",
-- which already prevents identity hijacking. But the row's role and
-- org_id columns are still mutable inside that constraint — an
-- athlete could PATCH their own profile with {role: "admin"} or
-- {org_id: "<other org>"}. The trigger guards those columns.
CREATE OR REPLACE FUNCTION public._enforce_profile_immutable_cols()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
BEGIN
  -- service_role bypass: triggers run under the calling role, so we
  -- check the JWT claim. The validate-invite endpoint runs with
  -- service_role and legitimately sets role + org_id on signup.
  IF current_setting('request.jwt.claim.role', true) IN ('service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'profiles.id is immutable';
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role THEN
    RAISE EXCEPTION 'profiles.role can only be changed by an administrator';
  END IF;

  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'profiles.org_id can only be changed by an administrator';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_enforce_immutable_cols ON public.profiles;

CREATE TRIGGER profiles_enforce_immutable_cols
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public._enforce_profile_immutable_cols();

-- ============ migrations/051_program_email_coverage.sql ============
-- 051_program_email_coverage.sql
--
-- Adds the metadata columns the women's soccer coach/program email
-- scraper writes after every pass. The scraper runs the full waterfall
-- of URL patterns (coach page → staff directory → bio page →
-- recruiting questionnaire → program landing page) and stores BOTH
-- the winning email AND the full candidate array for admin review.
--
-- Idempotent. Apply via Supabase SQL Editor (not `supabase db push` —
-- prod migration history is out of sync with the local repo).

ALTER TABLE public.schools
  ADD COLUMN IF NOT EXISTS program_email text,
  ADD COLUMN IF NOT EXISTS program_email_source text,
  ADD COLUMN IF NOT EXISTS program_email_confidence text,
  ADD COLUMN IF NOT EXISTS program_email_last_checked_at timestamptz,
  ADD COLUMN IF NOT EXISTS program_email_url text,
  ADD COLUMN IF NOT EXISTS program_email_failure_reason text,
  ADD COLUMN IF NOT EXISTS program_email_candidates jsonb;

-- Add CHECK constraints separately so re-running the migration on a
-- table that already has the columns (but maybe not the constraints)
-- still installs them. ALTER COLUMN ... ADD CONSTRAINT doesn't have an
-- IF NOT EXISTS, so we DROP first.
ALTER TABLE public.schools
  DROP CONSTRAINT IF EXISTS schools_program_email_source_check;
ALTER TABLE public.schools
  ADD CONSTRAINT schools_program_email_source_check
  CHECK (program_email_source IS NULL OR program_email_source IN (
    'coach_page',
    'staff_directory',
    'coach_bio',
    'recruiting_questionnaire',
    'athletics_contact',
    'manual',
    'unknown'
  ));

ALTER TABLE public.schools
  DROP CONSTRAINT IF EXISTS schools_program_email_confidence_check;
ALTER TABLE public.schools
  ADD CONSTRAINT schools_program_email_confidence_check
  CHECK (program_email_confidence IS NULL OR program_email_confidence IN (
    'verified',
    'likely',
    'missing'
  ));

-- Admin CSV export filters/orders by (confidence, division). The index
-- supports both the WHERE clause ("show me everything still missing")
-- and the per-division grouping.
CREATE INDEX IF NOT EXISTS idx_schools_program_email_confidence
  ON public.schools (program_email_confidence, division);

COMMENT ON COLUMN public.schools.program_email IS
  'Winning outreach email for this women''s soccer program (highest-scored candidate). May be verified or pattern-generated.';
COMMENT ON COLUMN public.schools.program_email_source IS
  'Which scraper strategy produced the winning email: coach_page, staff_directory, coach_bio, recruiting_questionnaire, athletics_contact, manual, unknown.';
COMMENT ON COLUMN public.schools.program_email_confidence IS
  'verified = pulled directly from an athletics page (mailto link or labeled coach card). likely = pattern-generated from name + domain, lower confidence. missing = scraper found nothing usable.';
COMMENT ON COLUMN public.schools.program_email_last_checked_at IS
  'Timestamp of the last scrape attempt for this school (success OR failure).';
COMMENT ON COLUMN public.schools.program_email_url IS
  'The athletics-site URL where the winning email was extracted (or last attempted on failure).';
COMMENT ON COLUMN public.schools.program_email_failure_reason IS
  'Set only when confidence=missing. One of: no_athletics_website, all_strategies_404, cloudflare_blocked, timeout, no_email_in_html, parse_error.';
COMMENT ON COLUMN public.schools.program_email_candidates IS
  'JSONB array of every email candidate found during the most recent scrape pass. Preserved for admin triage even when only one wins the program_email slot. Shape: [{email, role, name, source, url, confidence, score}, ...].';

-- ============ migrations/052_outreach_signature_redesign.sql ============
-- 052_outreach_signature_redesign.sql
--
-- Two changes that ship together because the signature template
-- references the new column:
--
--   1. athletes.phone — needed in the email signature so coaches can
--      text recruits (the standard recruiting flow). Optional; if
--      blank the substitution drops to an empty line, no placeholder.
--
--   2. Rewrite all six seeded outreach templates in a more authentic,
--      mobile-friendly athlete voice. The old templates read corporate
--      (bulleted stat block, three separate film links, "I'd love to
--      stay in touch as my recruiting process develops" boilerplate)
--      and didn't render well on a coach's phone — which is where
--      most recruiting email is actually read. New voice: concise,
--      conversational, one film link, signature block matches the
--      Name / Grad·Club·Position / Phone / Film format.
--
-- Idempotent: phone is ADD COLUMN IF NOT EXISTS; templates are
-- UPDATEs keyed on (template_type, org_id IS NULL) so re-running
-- against an environment that already has the new copy is a no-op.

-- ─── 1. Phone column ──────────────────────────────────────────────
ALTER TABLE public.athletes
  ADD COLUMN IF NOT EXISTS phone text;

COMMENT ON COLUMN public.athletes.phone IS
  'Athlete''s contact phone number for coach outreach. Optional. '
  'Rendered in outgoing email signatures when set, dropped silently '
  'when null/empty (the template uses the null-drop convention from '
  'substituteTemplate() in Outreach.jsx).';

-- ─── 2. Template rewrites ─────────────────────────────────────────
-- Each UPDATE only touches the SYSTEM templates (org_id IS NULL).
-- Org-customized templates are left alone so club directors who
-- already tuned their copy don't lose it.

-- Initial Contact
UPDATE public.outreach_templates
   SET subject_template =
        '{{grad_year}} {{position}} — {{athlete_name}}, interested in {{school_name}}',
       body_template =
'Hi Coach {{coach_name}},

I''m {{athlete_name}}, a {{grad_year}} {{position}} at {{high_school}} in {{city}}, {{state}}. I play club for {{club_team}}.

I''d like to be on your radar for {{school_name}}. GPA {{gpa}}, jersey #{{jersey_number}}.

Film: {{highlight_url}}

Happy to send more whenever it''s useful.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'initial' AND org_id IS NULL;

-- Follow-up Check-in
UPDATE public.outreach_templates
   SET subject_template =
        'Checking in — {{athlete_name}}, {{grad_year}} {{position}}',
       body_template =
'Hi Coach {{coach_name}},

Wanted to follow up on my earlier note. Still really interested in {{school_name}} and would love to stay connected.

Happy to send updated film or answer anything about my profile.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'follow_up' AND org_id IS NULL;

-- Highlight Share
UPDATE public.outreach_templates
   SET subject_template =
        'New film — {{athlete_name}}, {{grad_year}} {{position}}',
       body_template =
'Hi Coach {{coach_name}},

Just updated my highlight reel with recent game footage: {{highlight_url}}

Let me know if there''s anything specific you''d like to see more of.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'highlight_share' AND org_id IS NULL;

-- Campus Visit Request
UPDATE public.outreach_templates
   SET subject_template =
        'Campus visit — {{athlete_name}}, {{grad_year}} {{position}}',
       body_template =
'Hi Coach {{coach_name}},

I''d love to visit {{school_name}} and see the program. Any ID camps, prospect days, or open practices coming up?

Happy to set up an unofficial visit whenever works for your staff.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'campus_visit' AND org_id IS NULL;

-- Thank You After Camp
UPDATE public.outreach_templates
   SET subject_template =
        'Thank you — {{athlete_name}}, {{school_name}} camp',
       body_template =
'Hi Coach {{coach_name}},

Thanks for running a great camp this weekend. I really enjoyed the sessions and meeting the staff.

Looking forward to staying in touch.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'thank_you_camp' AND org_id IS NULL;

-- Schedule Update
UPDATE public.outreach_templates
   SET subject_template =
        'Upcoming games — {{athlete_name}}, {{grad_year}} {{position}}',
       body_template =
'Hi Coach {{coach_name}},

Wanted to share my upcoming schedule in case you''re in the area or scouting via video:

{{upcoming_games}}

Happy to send field locations or any logistical info.

{{athlete_name}}
{{grad_year}} · {{club_team}} · {{position}}
{{phone}}
{{highlight_url}}'
 WHERE template_type = 'schedule_update' AND org_id IS NULL;

-- ============ football/100_football_core.sql ============
-- 100_football_core.sql
-- Football conversion of the inherited KRS College Connect schema.
-- Applied after the inherited soccer migrations (see scripts/football/build-schema.py).

-- ─── 1. Columns production had but the migration history never recorded ───
ALTER TABLE public.outreach
  ADD COLUMN IF NOT EXISTS coach_id uuid REFERENCES public.coaches(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS school_id uuid REFERENCES public.schools(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS template_type text,
  ADD COLUMN IF NOT EXISTS coach_replied boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS coach_reply_status text,
  ADD COLUMN IF NOT EXISTS reply_received_at timestamptz;
CREATE INDEX IF NOT EXISTS idx_outreach_coach ON public.outreach (coach_id);
